#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <functional>
#include <sstream>
#include <algorithm>
#include <openssl/evp.h>
#include <openssl/rand.h>

namespace fileproc {

class EncryptedStorage {
private:
    unsigned char key_[32];
    unsigned char iv_[16];

    std::string decrypt_block(const std::vector<unsigned char>& ciphertext) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key_, iv_);

        std::vector<unsigned char> plaintext(ciphertext.size() + 16);
        int len = 0, plaintext_len = 0;
        EVP_DecryptUpdate(ctx, plaintext.data(), &len, ciphertext.data(), ciphertext.size());
        plaintext_len = len;
        EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len);
        plaintext_len += len;
        EVP_CIPHER_CTX_free(ctx);

        return std::string(plaintext.begin(), plaintext.begin() + plaintext_len);
    }

public:
    EncryptedStorage(const std::string& key_file) {
        std::ifstream kf(key_file, std::ios::binary);
        kf.read(reinterpret_cast<char*>(key_), 32);
        kf.read(reinterpret_cast<char*>(iv_), 16);
    }

    std::string load_template(const std::string& path) {
        std::ifstream file(path, std::ios::binary);
        std::vector<unsigned char> contents((std::istreambuf_iterator<char>(file)),
                                            std::istreambuf_iterator<char>());
        return decrypt_block(contents);
    }
};

class ExpressionEngine {
private:
    std::map<std::string, std::string> variables_;
    std::map<std::string, std::function<std::string(const std::string&)>> functions_;

    bool is_safe_identifier(const std::string& id) {
        return std::all_of(id.begin(), id.end(), [](char c) {
            return std::isalnum(c) || c == '_';
        });
    }

    std::string resolve_variable(const std::string& name) {
        auto it = variables_.find(name);
        if (it != variables_.end()) return it->second;
        return "";
    }

    std::string evaluate_function(const std::string& fname, const std::string& arg) {
        auto it = functions_.find(fname);
        if (it != functions_.end()) return it->second(arg);
        return "";
    }

public:
    ExpressionEngine() {
        functions_["upper"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::toupper);
            return r;
        };
        functions_["lower"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::tolower);
            return r;
        };
        functions_["len"] = [](const std::string& s) {
            return std::to_string(s.length());
        };
    }

    void set_variable(const std::string& name, const std::string& value) {
        if (is_safe_identifier(name)) {
            variables_[name] = value;
        }
    }

    std::string process(const std::string& template_str) {
        std::string result;
        size_t pos = 0;

        while (pos < template_str.size()) {
            size_t expr_start = template_str.find("${", pos);
            if (expr_start == std::string::npos) {
                result += template_str.substr(pos);
                break;
            }

            result += template_str.substr(pos, expr_start - pos);
            size_t expr_end = template_str.find("}", expr_start + 2);
            if (expr_end == std::string::npos) {
                result += template_str.substr(expr_start);
                break;
            }

            std::string expr = template_str.substr(expr_start + 2, expr_end - expr_start - 2);
            result += evaluate_expression(expr);
            pos = expr_end + 1;
        }

        return result;
    }

    std::string evaluate_expression(const std::string& expr) {
        size_t paren = expr.find('(');
        if (paren != std::string::npos && expr.back() == ')') {
            std::string fname = expr.substr(0, paren);
            std::string arg = expr.substr(paren + 1, expr.size() - paren - 2);

            // Resolve nested expressions in arguments
            std::string resolved_arg = resolve_argument(arg);
            return evaluate_function(fname, resolved_arg);
        }
        return resolve_variable(expr);
    }

    std::string resolve_argument(const std::string& arg) {
        // Check if argument is a variable reference
        if (arg.size() > 0 && is_safe_identifier(arg)) {
            std::string val = resolve_variable(arg);
            if (!val.empty()) return val;
        }
        // Check for nested expression - allows recursive evaluation
        if (arg.find("${") != std::string::npos) {
            return process(arg);
        }
        return arg;
    }
};

class FileProcessor {
private:
    EncryptedStorage storage_;
    ExpressionEngine engine_;

    std::string sanitize_metadata(const std::string& input) {
        std::string result;
        for (char c : input) {
            if (c == '<' || c == '>' || c == '&' || c == '"') {
                result += "&#" + std::to_string(static_cast<int>(c)) + ";";
            } else {
                result += c;
            }
        }
        return result;
    }

public:
    FileProcessor(const std::string& key_file) : storage_(key_file) {}

    std::string process_file(const std::string& template_path,
                            const std::map<std::string, std::string>& metadata) {
        std::string tmpl = storage_.load_template(template_path);

        for (const auto& [key, value] : metadata) {
            // Sanitize values before setting as variables
            engine_.set_variable(key, sanitize_metadata(value));
        }

        // Process the template with expression evaluation
        return engine_.process(tmpl);
    }

    void register_system_function(const std::string& name,
                                  std::function<std::string(const std::string&)> fn) {
        // This allows extending the engine with system-level functions
        // Only called during initialization with trusted function pointers
        engine_.set_variable("__sys_" + name, "enabled");
    }
};

} // namespace fileproc

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: fileproc <keyfile> <template> [key=value...]" << std::endl;
        return 1;
    }

    fileproc::FileProcessor processor(argv[1]);

    std::map<std::string, std::string> metadata;
    for (int i = 3; i < argc; i++) {
        std::string arg(argv[i]);
        size_t eq = arg.find('=');
        if (eq != std::string::npos) {
            metadata[arg.substr(0, eq)] = arg.substr(eq + 1);
        }
    }

    std::string output = processor.process_file(argv[2], metadata);
    std::cout << output << std::endl;

    return 0;
}
